    New-ConsoleRows -Gap 1 {
        '[bold]Fleet health[/] [muted]· synthetic inventory[/]'
        New-ConsolePanel -Title 'Fleet summary' {
            '[pass]2 healthy[/]  [warn]1 warning[/]  [fail]1 offline[/]  [accent]1 running[/]'
        }

