    new { Host = "sql-01", Role = "Database", Site = "North", Status = "Pass" },
    new { Host = "sql-02", Role = "Database", Site = "West", Status = "Fail" },
    new { Host = "job-01", Role = "Worker", Site = "West", Status = "Running" }
};
